# Review package: 70aa24dbd036ffe4ab8bd7a64b7ae4ae9cac841e..HEAD

## Commits
e45bc26 Add greet function with formatted greeting

## Files changed
 greet.js      | 10 ++++++++++
 greet.test.js | 28 ++++++++++++++++++++++++++++
 2 files changed, 38 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..ecd9ad9
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,10 @@
+function greet(name) {
+  // Handle empty, null, undefined, or whitespace-only input
+  if (!name || typeof name !== 'string' || name.trim() === '') {
+    return 'Greetings, friend!';
+  }
+
+  return `Greetings, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..d69e9bc
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,28 @@
+const { test } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for valid name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Greetings, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Greetings, friend!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Greetings, friend!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Greetings, friend!');
+});
+
+test('greet handles whitespace-only input gracefully', () => {
+  const result = greet('   ');
+  assert.strictEqual(result, 'Greetings, friend!');
+});
